using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;
partial class AvalonInterno {
 readonly CheckBox[] attackRows=new CheckBox[9];
 // The principal can take part in the attack too (both modes); on by default, saved in config.txt.
 readonly CheckBox primaryAttack=new TickBox{Checked=true};readonly ComboBox attackMode=new CyanCombo();TextBox attackKey=new TextBox();Keys attackChoice=Keys.D1;bool attackCtrl,attackAlt,attackShift,attackRequested,attackStopRequested,attackStopping;int savedAttackMode=1;AttackController attacks;Task attackJob=Task.FromResult(0);
 string AttackKeyText(){return(attackCtrl?"Ctrl+":"")+(attackAlt?"Alt+":"")+(attackShift?"Shift+":"")+attackChoice;}
 void AttackKeyEditor(int x,int y){attackKey.SetBounds(x,y,58,16);attackKey.ReadOnly=true;attackKey.BorderStyle=BorderStyle.None;attackKey.Text=AttackKeyText();attackKey.TextAlign=HorizontalAlignment.Center;attackKey.BackColor=Color.Black;attackKey.ForeColor=Color.Cyan;attackKey.Font=new Font("Segoe UI",(float)(8)*global::UiScale.F);attackKey.KeyDown+=(o,e)=>{e.SuppressKeyPress=true;if(busy||e.KeyCode==Keys.ControlKey||e.KeyCode==Keys.ShiftKey||e.KeyCode==Keys.Menu)return;attackChoice=e.KeyCode;attackCtrl=e.Control;attackAlt=e.Alt;attackShift=e.Shift;attackKey.Text=AttackKeyText();Save();};Controls.Add(attackKey);hints.SetToolTip(attackKey,"Tecla para iniciar a macro 0 no modo Manual. Padrão: 1.");}
 void InitAttack(){AddLabel("Modo de ataque",270,191,143,18,new Font("Segoe UI",(float)(8)*global::UiScale.F),Color.White);attackMode.SetBounds(270,212,143,28);attackMode.DropDownStyle=ComboBoxStyle.DropDownList;attackMode.Items.AddRange(new object[]{"Automático","Manual por tecla"});attackMode.SelectedIndex=1;attackMode.SelectedIndexChanged+=(o,e)=>{StopAttackRepeat(null);RequestAttackStop();if(!syncing){savedAttackMode=attackMode.SelectedIndex;Save();}};Controls.Add(attackMode);hints.SetToolTip(attackMode,"Automático: enquanto o principal tiver um monstro selecionado, os secundários repetem a macro 0; selecione você mesmo para parar. Manual: uma vez por tecla Atacar. Participam os secundários marcados.");AttackModeKeyEditor();primaryAttack.CheckedChanged+=(o,e)=>{RequestAttackStop();if(!syncing)Save();};for(int i=0;i<attackRows.Length;i++){int k=i;var sup=new TickBox{Visible=false,FlatStyle=FlatStyle.Flat,ForeColor=SupportColor,AccessibleName="Suporte com o secundário "+(i+1)};sup.CheckedChanged+=(o,e)=>SupportStateChanged(k);supportRows[i]=sup;Controls.Add(sup);hints.SetToolTip(sup,"Sacerdote: suporte ao líder com a macro 2 durante o combo (no lugar do ataque).");attackRows[i].CheckedChanged+=(o,e)=>AttackStateChanged(k);}Controls.Add(primaryAttack);hints.SetToolTip(primaryAttack,"O principal também ataca com a macro 0 (Automático e Manual).");attacks=new AttackController(new NativeAttackRuntime(),blocked,s=>{if(!IsDisposed)BeginInvoke(new Action(()=>Note(s)));});}
 // Programmable key that switches the attack mode between Automático and Manual por tecla (unset by default; Delete clears).
 TextBox attackModeKey=new TextBox();Keys attackModeChoice=Keys.None;bool attackModeCtrl,attackModeAlt,attackModeShift;
 string AttackModeKeyText(){return attackModeChoice==Keys.None?"—":(attackModeCtrl?"Ctrl+":"")+(attackModeAlt?"Alt+":"")+(attackModeShift?"Shift+":"")+attackModeChoice;}
 void AttackModeKeyEditor(){attackModeKey.ReadOnly=true;attackModeKey.TextAlign=HorizontalAlignment.Center;attackModeKey.Text=AttackModeKeyText();attackModeKey.KeyDown+=(o,e)=>{e.SuppressKeyPress=true;if(busy||e.KeyCode==Keys.ControlKey||e.KeyCode==Keys.ShiftKey||e.KeyCode==Keys.Menu)return;if(e.KeyCode==Keys.Delete||e.KeyCode==Keys.Back){attackModeChoice=Keys.None;attackModeCtrl=attackModeAlt=attackModeShift=false;}else{attackModeChoice=e.KeyCode;attackModeCtrl=e.Control;attackModeAlt=e.Alt;attackModeShift=e.Shift;}attackModeKey.Text=AttackModeKeyText();Save();};Controls.Add(attackModeKey);hints.SetToolTip(attackModeKey,"Tecla que alterna o modo de ataque entre Automático e Manual por tecla. Delete apaga.");}
 void BindAttackMode(){attackModeKey.Text=AttackModeKeyText();Win.UnregisterHotKey(Handle,6);if(!shortcutActive||!gameInFront||controlLocked||attackModeChoice==Keys.None)return;uint mods=0x4000|(attackModeCtrl?2u:0u)|(attackModeAlt?1u:0u)|(attackModeShift?4u:0u);Note(Win.RegisterHotKey(Handle,6,mods,(uint)attackModeChoice)?"Modo de ataque: atalho "+AttackModeKeyText():"Tecla do modo de ataque ocupada; escolha outra.");}
 Task ToggleAttackMode(){if(closeInProgress)return Task.FromResult(0);CancelBuffWait();attackMode.SelectedIndex=attackMode.SelectedIndex==0?1:0;string mode=attackMode.SelectedIndex==0?"Automático":"Manual por tecla";Note("Modo de ataque: "+mode+".");status.Text="Modo de ataque · "+mode;return Task.FromResult(0);}
 void BindAttack(){BindAttackMode();attackKey.Text=AttackKeyText();Win.UnregisterHotKey(Handle,5);if(!shortcutActive||!gameInFront||controlLocked)return;uint mods=0x4000|(attackCtrl?2u:0u)|(attackAlt?1u:0u)|(attackShift?4u:0u);Note(Win.RegisterHotKey(Handle,5,mods,(uint)attackChoice)?"Atacar: atalho "+AttackKeyText():"Tecla de Atacar ocupada; escolha outra.");}
 // A sacerdote's row shows a second box, Sup (green): support the leader with macro 2 instead of attacking. Atk and Sup exclude each other.
 static readonly Color SupportColor=Color.FromArgb(110,205,120);
 readonly CheckBox[] supportRows=new CheckBox[9];
 // 0.39.0 (owner): a character put in a slot starts attacking (a priest starts in support); the boxes can be changed any time.
 readonly int[] rolePid=new int[9];
 void UpdateAttackRows(){FillSupportTargets();for(int i=0;i<9;i++){var entry=rows[i].SelectedItem as Entry;bool selected=entry!=null;attackRows[i].Enabled=selected;bool cleric=selected&&entry.Class==ClassIcons.Cleric;if(supportRows[i]!=null){supportRows[i].Visible=cleric;if(!cleric)supportRows[i].Checked=false;}
  if(!selected){attackRows[i].Checked=false;rolePid[i]=0;continue;}if(rolePid[i]==entry.Pid)continue;rolePid[i]=entry.Pid;if(cleric&&supportRows[i]!=null){attackRows[i].Checked=false;supportRows[i].Checked=true;}else attackRows[i].Checked=true;}}
 void SupportStateChanged(int i){var sup=supportRows[i];if(sup.Checked&&attackRows[i].Checked)attackRows[i].Checked=false;var entry=rows[i].SelectedItem as Entry;if(entry!=null&&!syncing){RequestAttackStop();Note(entry.Name+(sup.Checked?": suporte ao líder (macro 2).":": suporte desligado."));}}
 void AttackStateChanged(int i){if(supportRows[i]!=null&&attackRows[i].Checked&&supportRows[i].Checked)supportRows[i].Checked=false;}
 void RequestAttackStop(){attackStopRequested=true;attackRequested=false;}
 Task RequestAttack(){if(closeInProgress)return Task.FromResult(0);CancelBuffWait();if(MeditationPause){Note("Levante o principal antes de atacar.");return Task.FromResult(0);}string keyRefusal=AttackHotkey.Refusal(shortcutActive,attackMode.SelectedIndex);if(keyRefusal!=null){Note(keyRefusal);return Task.FromResult(0);}if(busy||teleport.Working||missions.Working){Note("Aguarde a operação atual para atacar.");return Task.FromResult(0);}if(!primaryAttack.Checked&&!attackRows.Any(c=>c.Enabled&&c.Checked)&&!supportRows.Any(c=>c!=null&&c.Visible&&c.Checked)){Note("Marque Atacar no principal ou nos secundários desejados.");return Task.FromResult(0);}var primary=main.SelectedItem as Entry;if(primary==null){Note("Escolha o principal.");return Task.FromResult(0);}try{if(!AttackController.MonsterId(attacks.ReadTarget(primary.Ref()))){Note("Selecione um monstro no principal antes de apertar Atacar.");return Task.FromResult(0);}}catch(Exception e){Note("Ataque: "+e.Message);return Task.FromResult(0);}attackAccepted=true;attackRequested=true;return AttackTick();}
 // Periodic tick: busy alone guards the action button; toggling Enabled every 300 ms made its text blink.
 async Task AttackTick(){if(attacks==null||altoOn||closeInProgress||busy||buffing||MeditationPause||attackStopping||!attackJob.IsCompleted||teleport.Working||missions.Working)return;var primary=main.SelectedItem as Entry;var selected=rows.Where((row,i)=>attackRows[i].Enabled&&(attackRows[i].Checked||supportRows[i].Checked)).Select(row=>row.SelectedItem as Entry).Where(e=>e!=null&&primary!=null&&e.Pid!=primary.Pid&&!RotaLock.Busy(e.Pid)&&!ResBusy(e.Pid)&&!IsDead(e.Pid)&&!FoxBusy(e.Pid)).Select(e=>e.Ref()).ToArray();if(primary!=null&&primaryAttack.Checked&&!RotaLock.Busy(primary.Pid)&&!ResBusy(primary.Pid)&&!IsDead(primary.Pid)&&!FoxBusy(primary.Pid))selected=new[]{primary.Ref()}.Concat(selected).ToArray();var support=new HashSet<int>(rows.Where((row,i)=>attackRows[i].Enabled&&supportRows[i].Checked).Select(row=>row.SelectedItem as Entry).Where(e=>e!=null&&primary!=null&&e.Pid!=primary.Pid).Select(e=>e.Pid));var supportOn=SupportTargetRef(primary);bool stop=attackStopRequested,request=attackRequested,automatic=attackMode.SelectedIndex==0,enabled=shortcutActive;attackStopRequested=attackRequested=false;busy=true;attackTicking=true;try{attackJob=Task.Run(()=>{if(stop)attacks.StopAll();attacks.Tick(primary==null?null:primary.Ref(),selected,enabled,automatic,request,support,supportOn);});await attackJob;}catch(Exception e){attackStopRequested=true;Note("Ataque: "+e.Message);}finally{busy=false;attackTicking=false;}
  if(attacks.TakeReleased()&&!closeInProgress)await FollowNowAll();}
 async Task StopAttacks(){RequestAttackStop();if(attacks==null)return;bool ownsBusy=!busy;busy=true;attackStopping=true;try{try{await attackJob;}catch(Exception e){Note("Ataque anterior: "+e.Message);}await Task.Run(()=>attacks.StopAll());attackStopRequested=false;}finally{attackStopping=false;if(ownsBusy)busy=false;}}
 bool AttackEngaged(int pid){return attackStopping||attacks!=null&&attacks.Engaged(pid);}
